lhs_symbols":["S-PROFIT"],"rhs_symbols":["S-D4"],"equation_type":"DERIVED","unit":"dimensionless","depends_on":["EQ-PROFIT-DEF"],"source":"e1","e1_span":"回流可以用几何级数求和处理"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-CONF-INTERVAL","scope_ref":"P4","expression":"[p_lower, p_upper]","representation":"LATEX_PRESENTATION","lhs_symbols":["S-P-UPPER"],"rhs_symbols":["S-X","S-N"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"e1","e1_span":"构造p的置信区间[p_lower, p_upper]"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-ROBUST-OPT","scope_ref":"P4","expression":"use p_upper in decision","representation":"LATEX_PRESENTATION","lhs_symbols":["S-DEC-Q4"],"rhs_symbols":["S-P-UPPER"],"equation_type":"OBJECTIVE","unit":"dimensionless","depends_on":["EQ-CONF-INTERVAL"],"source":"e1","e1_span":"在鲁棒优化中，用p_upper代替p进行决策，这样得到的决策在最坏情况下仍然是最优的"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-Q3-RECURSION","scope_ref":"P3","expression":"C_j = f(C_i, d_i)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PROFIT-Q3"],"rhs_symbols":["S-DEC-Q3"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"e1","e1_span":"从最底层零配件开始，逐层向上递推"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-Q3-PROFIT","scope_ref":"P3","expression":"profit = revenue - cost","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PROFIT-Q3"],"rhs_symbols":["S-DEC-Q3"],"equation_type":"OBJECTIVE","unit":"dimensionless","depends_on":["EQ-Q3-RECURSION"],"source":"e1","e1_span":"对成品，计算期望利润（考虑市场售价、调换损失、拆解决策）"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-Q4-PROFIT","scope_ref":"P4","expression":"profit = max over strategies with p_upper","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PROFIT-Q4"],"rhs_symbols":["S-P-UPPER","S-DEC-Q4"],"equation_type":"OBJECTIVE","unit":"dimensionless","depends_on":["EQ-CONF-INTERVAL","EQ-ROBUST-OPT"],"source":"e1","e1_span":"对问题2的每种情形，用次品率的置信区间上界重新计算16种策略的期望利润，取最大者"}},{"kind":"ModelSpec","value":{"model_id":"M1","problem_refs":["P1"],"assumption_refs":["A-BINOMIAL-SAMPLING","A-INFINITE-BATCH","A-PERFECT-TEST"],"variable_refs":["S-N","S-C"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.1},{"symbol_ref":"S-ALPHA","value":0.05}],"equation_refs":["EQ-BINOM-CDF","EQ-REJECT-COND","EQ-ACCEPT-COND","EQ-MIN-N-C"],"constraints":[],"objective":"minimize sample size n","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M2","problem_refs":["P2"],"assumption_refs":["A-INDEPENDENT-PARTS","A-PERFECT-TEST","A-NO-DAMAGE-DISASSEMBLY","A-RETURN-REPEAT","A-INFINITE-BATCH"],"variable_refs":["S-DEC-Q2","S-PROFIT"],"parameter_refs":[{"symbol_ref":"S-P1","value":0.1},{"symbol_ref":"S-P2","value":0.1},{"symbol_ref":"S-PF","value":0.1},{"symbol_ref":"S-CP1","value":4},{"symbol_ref":"S-CP2","value":18},{"symbol_ref":"S-CT1","value":2},{"symbol_ref":"S-CT2","value":3},{"symbol_ref":"S-CTF","value":3},{"symbol_ref":"S-CA","value":6},{"symbol_ref":"S-R","value":56},{"symbol_ref":"S-CL","value":6},{"symbol_ref":"S-CD","value":5}],"equation_refs":["EQ-PROFIT-DEF","EQ-GEOMETRIC-RECYCLE"],"constraints":[],"objective":"maximize expected profit","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M3","problem_refs":["P3"],"assumption_refs":["A-INDEPENDENT-PARTS","A-PERFECT-TEST","A-NO-DAMAGE-DISASSEMBLY","A-RETURN-REPEAT","A-INFINITE-BATCH"],"variable_refs":["S-DEC-Q3","S-PROFIT-Q3"],"parameter_refs":[],"equation_refs":["EQ-Q3-RECURSION","EQ-Q3-PROFIT"],"constraints":[],"objective":"maximize expected profit","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M4","problem_refs":["P4"],"assumption_refs":["A-BINOMIAL-SAMPLING","A-INDEPENDENT-PARTS","A-PERFECT-TEST","A-NO-DAMAGE-DISASSEMBLY","A-RETURN-REPEAT","A-INFINITE-BATCH"],"variable_refs":["S-DEC-Q4","S-PROFIT-Q4"],"parameter_refs":[],"equation_refs":["EQ-CONF-INTERVAL","EQ-ROBUST-OPT","EQ-Q4-PROFIT"],"constraints":[],"objective":"maximize worst-case expected profit","dependencies":[]}}],"code":"const fs = require('fs');
function binomCDF(n, c, p) {
  if (c < 0) return 0;
  if (c >= n) return 1;
  let term = Math.pow(1 - p, n);
  let sum = term;
  for (let k = 1; k <= c; k++) {
    term = term * (n - k + 1) / k * p / (1 - p);
    sum += term;
  }
  return sum;
}
let p0 = 0.1;
let n_fixed = -1, c_fixed = -1;
for (let n = 1; n <= 100000; n++) {
  let found = false;
  for (let c = 0; c < n; c++) {
    if (binomCDF(n, c, p0) >= 0.95) { n_fixed = n; c_fixed = c; found = true; break; }
  }
  if (found) break;
}
const cases = [
  {p1:0.10,p2:0.10,pf:0.10,cp1:4,cp2:18,ct1:2,ct2:3,ctf:3,ca:6,r:56,cl:6,cd:5},
  {p1:0.20,p2:0.20,pf:0.20,cp1:4,cp2:18,ct1:2,ct2:3,ctf:3,ca:6,r:56,cl:6,cd:5},
  {p1:0.10,p2:0.10,pf:0.10,cp1:4,cp2:18,ct1:2,ct2:3,ctf:3,ca:6,r:56,cl:30,cd:5},
  {p1:0.20,p2:0.20,pf:0.20,cp1:4,cp2:18,ct1:1,ct2:1,ctf:2,ca:6,r:56,cl:30,cd:5},
  {p1:0.10,p2:0.20,pf:0.10,cp1:4,cp2:18,ct1:8,ct2:1,ctf:2,ca:6,r:56,cl:10,cd:5},
  {p1:0.05,p2:0.40,pf:0.10,cp1:4,cp2:18,ct1:2,ct2:3,ctf:3,ca:6,r:56,cl:10,cd:40}
];
function profit(cs, d1, d2, d3, d4) {
  const q1 = d1 ? 0 : cs.p1;
  const q2 = d2 ? 0 : cs.p2;
  const c1 = d1 ? (cs.cp1/(1-cs.p1) + cs.ct1) : cs.cp1;
  const c2 = d2 ? (cs.cp2/(1-cs.p2) + cs.ct2) : cs.cp2;
  const g = (1-q1)*(1-q2)*(1-cs.pf);
  const b = 1 - g;
  const base = c1 + c2 + cs.ca;
  let revenue = cs.r * g;
  let cost = base;
  if (d3) {
    cost += cs.ctf;
    if (d4) { cost += cs.cd * b - (cs.cp1+cs.cp2)*b; }
  } else {
    cost += cs.cl * b;
    if (d4) { cost += cs.cd * b - (cs.cp1+cs.cp2)*b; }
  }
  return revenue - cost;
}
function bestStrategy(cs) {
  let best = -Infinity, bestD = 0;
  for (let d = 0; d < 16; d++) {
    const p = profit(cs, (d>>0)&1, (d>>1)&1, (d>>2)&1, (d>>3)&1);
    if (p > best) { best = p; bestD = d; }
  }
  return {profit: best, decision: bestD};
}
const q2 = bestStrategy(cases[0]);
const q2profits = cases.map(c => bestStrategy(c).profit);
const q2decisions = cases.map(c => bestStrategy(c).decision);
const q3case = {p1:0.10,p2:0.10,pf:0.10,cp1:4,cp2:18,ct1:2,ct2:3,ctf:3,ca:6,r:56,cl:6,cd:5};
const q3 = bestStrategy(q3case);
function pUpper(x, n, alpha) {
  if (x >= n) return 1;
  let lo = 0, hi = 1;
  for (let i = 0; i < 200; i++) {
    const mid = (lo + hi) / 2;
    if (binomCDF(n, x, mid) > alpha) hi = mid; else lo = mid;
  }
  return (lo + hi) / 2;
}
const p_upper = pUpper(c_fixed, n_fixed, 0.05);
const q4case = {p1:p_upper,p2:p_upper,pf:p_upper,cp1:4,cp2:18,ct1:2,ct2:3,ctf:3,ca:6,r:56,cl:6,cd:5};
const q4 = bestStrategy(q4case);
fs.writeFileSync('q1.json', JSON.stringify({n: n_fixed, c: c_fixed}));
